WITH profit_per_customer AS ( SELECT c.c_customer_id, c.c_first_name, c.c_last_name, ib.ib_income_band_sk, ib.ib_lower_bound, ib.ib_upper_bound, hd.hd_buy_potential, SUM(ss.ss_net_profit) AS total_profit, c.c_birth_year FROM customer c JOIN household_demographics hd ON c.c_current_hdemo_sk = hd.hd_demo_sk JOIN income_band ib ON hd.hd_income_band_sk = ib.ib_income_band_sk JOIN store_sales ss ON ss.ss_customer_sk = c.c_customer_sk GROUP BY c.c_customer_id, c.c_first_name, c.c_last_name, ib.ib_income_band_sk, ib.ib_lower_bound, ib.ib_upper_bound, hd.hd_buy_potential, c.c_birth_year ), ranked_customers AS ( SELECT ppc.*, DENSE_RANK() OVER (PARTITION BY ppc.ib_income_band_sk ORDER BY ppc.total_profit DESC) AS profit_rank_in_band, SUM(ppc.total_profit) OVER (PARTITION BY ppc.ib_income_band_sk) AS band_total_profit FROM profit_per_customer ppc ) SELECT rc.c_customer_id, rc.c_first_name, rc.c_last_name, rc.ib_lower_bound, rc.ib_upper_bound, rc.hd_buy_potential, rc.total_profit, rc.profit_rank_in_band, rc.band_total_profit, (rc.total_profit / rc.band_total_profit) * 100 AS profit_pct_of_band FROM ranked_customers rc WHERE rc.profit_rank_in_band <= 4 ORDER BY rc.ib_income_band_sk, rc.profit_rank_in_band
